insert into alloc.decisions(decided_on,key,title,status,detail,repo_ref) values (date '2026-11-04','structure','Structure: U18 growth, U12 active, U15 passive, UOB','approved','Core = U12+U15+UOB','decisions/0010-alloc-two-sleeves-and-hedge.md'),(date '2026-11-04','u18_guardrails','U18 guard-rails: leverage<=1.5x, excess liquidity>40%, drawdown ladder 15/25/30, no naked short options, turnover<=2x NAV','approved','12-month probation; close or cut if net Sharpe<0.3','decisions/0010-alloc-two-sleeves-and-hedge.md'),(date '2026-11-04','scoreboard','Beat ALLW = vol-matched, rolling 12 and 36 months, after costs','approved','Raw return shown as second view','decisions/0010-alloc-two-sleeves-and-hedge.md'),(date '2026-11-04','hedge_scope','Option hedge covers the whole book including UOB, held in U18, cost<=2% of hedged value a year','approved',null,'decisions/0010-alloc-two-sleeves-and-hedge.md'),(date '2026-11-04','hedge_choice','H2: buy 4 SPY 690P / sell 4 SPY 615P, expiry 2027-02-19; cap book loss ~6% if SPY -20% over 3 months','proposed','Owner to choose cap and hedge; nothing placed','decisions/0010-alloc-two-sleeves-and-hedge.md'),(date '2026-11-04','account_rules','U12: review at 30d, stop -10%, <=15% per name, <=20% of book, turnover<=6x; U15: hold>=30d, bands, turnover<=1x; no options in U12/U15','proposed','Owner to confirm','decisions/0010-alloc-two-sleeves-and-hedge.md');
